'use strict';
// Paymint - single-file build (landing + customer portal + admin/shopkeeper panel + API). Zero dependencies.
// Run: node --experimental-sqlite index.js
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { DatabaseSync } = require('node:sqlite');

const EMBEDDED_HTML = Buffer.from('', 'base64').toString('utf8');
const EMBEDDED_LANDING = Buffer.from('', 'base64').toString('utf8');
const EMBEDDED_CUSTOMER = Buffer.from('', 'base64').toString('utf8');

// ---------- auth ----------
'use strict';
// Zero-dependency auth: scrypt password hashing + HMAC-signed tokens (JWT-like).

const SECRET = process.env.APP_SECRET || 'dev-secret-change-me';

function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const hash = crypto.scryptSync(String(password), salt, 32);
  return `scrypt$${salt.toString('hex')}$${hash.toString('hex')}`;
}

function verifyPassword(password, stored) {
  try {
    const [, saltHex, hashHex] = stored.split('$');
    const salt = Buffer.from(saltHex, 'hex');
    const expected = Buffer.from(hashHex, 'hex');
    const actual = crypto.scryptSync(String(password), salt, 32);
    return crypto.timingSafeEqual(actual, expected);
  } catch {
    return false;
  }
}

function b64url(buf) {
  return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function b64urlJson(obj) {
  return b64url(JSON.stringify(obj));
}
function fromB64url(str) {
  return Buffer.from(str.replace(/-/g, '+').replace(/_/g, '/'), 'base64');
}

// Minimal JWT (HS256).
function signToken(payload, expiresInSec = 60 * 60 * 24 * 7) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const body = { ...payload, iat: Math.floor(Date.now() / 1000), exp: Math.floor(Date.now() / 1000) + expiresInSec };
  const data = `${b64urlJson(header)}.${b64urlJson(body)}`;
  const sig = b64url(crypto.createHmac('sha256', SECRET).update(data).digest());
  return `${data}.${sig}`;
}

function verifyToken(token) {
  try {
    const [h, p, s] = String(token).split('.');
    if (!h || !p || !s) return null;
    const data = `${h}.${p}`;
    const expected = b64url(crypto.createHmac('sha256', SECRET).update(data).digest());
    const a = Buffer.from(s);
    const b = Buffer.from(expected);
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
    const payload = JSON.parse(fromB64url(p).toString('utf8'));
    if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) return null;
    return payload;
  } catch {
    return null;
  }
}



// ---------- db ----------
'use strict';
// Zero-dependency SQLite layer using Node's built-in node:sqlite (Node 22+).

const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
fs.mkdirSync(DATA_DIR, { recursive: true });
const DB_PATH = process.env.DB_PATH || path.join(DATA_DIR, 'paymint.db');

const db = new DatabaseSync(DB_PATH);
db.exec('PRAGMA journal_mode = WAL;');
db.exec('PRAGMA foreign_keys = ON;');

db.exec(`
CREATE TABLE IF NOT EXISTS users (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  role         TEXT NOT NULL CHECK(role IN ('admin','agent')),
  name         TEXT NOT NULL,
  shop_name    TEXT,
  phone        TEXT UNIQUE NOT NULL,
  password     TEXT NOT NULL,           -- scrypt hash
  status       TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended')),
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS customers (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  agent_id     INTEGER NOT NULL REFERENCES users(id),
  name         TEXT NOT NULL,
  phone        TEXT NOT NULL,
  cnic         TEXT,                     -- CNIC number
  selfie_path  TEXT,                     -- stored image file
  cnic_path    TEXT,                     -- stored image file
  product      TEXT,                     -- what was sold (e.g. phone model)
  total_price  REAL NOT NULL DEFAULT 0,
  down_payment REAL NOT NULL DEFAULT 0,
  months       INTEGER NOT NULL DEFAULT 0,
  status       TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','rejected','completed')),
  reject_reason TEXT,
  device_locked INTEGER NOT NULL DEFAULT 0,  -- 0/1, controlled after missed payment
  device_id    TEXT,                     -- registered lock-app device identifier
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS payment_requests (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  customer_id   INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  installment_id INTEGER REFERENCES installments(id) ON DELETE SET NULL,
  amount        REAL NOT NULL DEFAULT 0,
  method        TEXT,                    -- jazzcash / easypaisa / cash
  txn_ref       TEXT,
  status        TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS installments (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  customer_id  INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  seq          INTEGER NOT NULL,         -- 1..months
  amount       REAL NOT NULL,
  due_date     TEXT NOT NULL,            -- YYYY-MM-DD
  paid         INTEGER NOT NULL DEFAULT 0,
  paid_at      TEXT,
  method       TEXT,                     -- jazzcash / easypaisa / cash
  txn_ref      TEXT
);

CREATE TABLE IF NOT EXISTS leads (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  type         TEXT NOT NULL DEFAULT 'general',  -- dealer / customer / general
  name         TEXT NOT NULL,
  phone        TEXT,
  email        TEXT,
  message      TEXT,
  status       TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','done')),
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_customers_agent ON customers(agent_id);
CREATE INDEX IF NOT EXISTS idx_inst_customer ON installments(customer_id);
CREATE INDEX IF NOT EXISTS idx_inst_due ON installments(due_date, paid);
`);

// --- migrations for older databases ---
function addColumn(table, col, decl) {
  const cols = db.prepare(`PRAGMA table_info(${table})`).all().map(c => c.name);
  if (!cols.includes(col)) db.exec(`ALTER TABLE ${table} ADD COLUMN ${col} ${decl}`);
}
addColumn('customers', 'pin', 'TEXT'); // hashed customer login PIN
addColumn('customers', 'force_lock', 'INTEGER'); // manual test override: 1=lock, 0=unlock, null=auto
addColumn('customers', 'joint_path', 'TEXT');   // customer + shopkeeper together photo



// ---------- seed admin on startup (idempotent) ----------
(function(){
  const existing = db.prepare("SELECT id FROM users WHERE role='admin'").get();
  if(!existing){
    const phone = process.env.ADMIN_PHONE || '03000000000';
    const pass = process.env.ADMIN_PASSWORD || 'admin123';
    const name = process.env.ADMIN_NAME || 'Owner';
    db.prepare("INSERT INTO users (role,name,phone,password,status) VALUES ('admin',?,?,?, 'active')").run(name, phone, hashPassword(pass));
    console.log('Admin seeded: phone=' + phone);
  }
})();

// ---------- server ----------
'use strict';
// Zero-dependency HTTP server for Paymint backend + dashboard.

const PORT = process.env.PORT || 3000;
const UPLOAD_DIR = process.env.UPLOAD_DIR || path.join(DATA_DIR, 'uploads');
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

// ---------- tiny helpers ----------
function send(res, status, body, headers = {}) {
  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', ...headers });
  res.end(payload);
}
function readBody(req, limit = 30 * 1024 * 1024) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) { reject(new Error('payload too large')); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return resolve({});
      try { resolve(JSON.parse(raw)); } catch { reject(new Error('invalid JSON')); }
    });
    req.on('error', reject);
  });
}
function today() { return new Date().toISOString().slice(0, 10); }
function addMonths(dateStr, n) {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCMonth(d.getUTCMonth() + n);
  return d.toISOString().slice(0, 10);
}
function saveImage(dataUrl, prefix) {
  if (!dataUrl || typeof dataUrl !== 'string') return null;
  const m = dataUrl.match(/^data:(image\/(png|jpe?g|webp));base64,(.+)$/);
  if (!m) return null;
  const ext = m[2] === 'jpeg' ? 'jpg' : m[2];
  const name = `${prefix}_${Date.now()}_${crypto.randomBytes(4).toString('hex')}.${ext}`;
  fs.writeFileSync(path.join(UPLOAD_DIR, name), Buffer.from(m[3], 'base64'));
  return name;
}

// ---------- auth middleware ----------
function authUser(req) {
  const h = req.headers['authorization'] || '';
  const token = h.startsWith('Bearer ') ? h.slice(7) : null;
  if (!token) return null;
  const payload = verifyToken(token);
  if (!payload || payload.uid == null) return null;
  const user = db.prepare('SELECT id, role, name, shop_name, phone, status FROM users WHERE id = ?').get(payload.uid);
  if (!user || user.status !== 'active') return null;
  return user;
}

// ---------- domain logic ----------
function generateSchedule(customer) {
  const principal = Math.max(0, customer.total_price - customer.down_payment);
  const months = customer.months;
  if (months <= 0) return;
  const base = Math.floor((principal / months) * 100) / 100;
  let allocated = 0;
  const stmt = db.prepare('INSERT INTO installments (customer_id, seq, amount, due_date) VALUES (?,?,?,?)');
  for (let i = 1; i <= months; i++) {
    let amt = base;
    if (i === months) amt = Math.round((principal - allocated) * 100) / 100; // last catches rounding
    allocated += base;
    stmt.run(customer.id, i, amt, addMonths(today(), i));
  }
}

// A customer SHOULD be locked if any installment is overdue and unpaid.
function overdueCount(customerId) {
  return db.prepare(
    "SELECT COUNT(*) c FROM installments WHERE customer_id = ? AND paid = 0 AND due_date < ?"
  ).get(customerId, today()).c;
}
function refreshLockState(customerId) {
  const c = db.prepare('SELECT status, force_lock FROM customers WHERE id = ?').get(customerId);
  if (!c) return;
  let locked;
  if (c.force_lock === 1) locked = 1;           // manual test lock
  else if (c.force_lock === 0) locked = 0;       // manual test unlock
  else locked = c.status === 'active' && overdueCount(customerId) > 0 ? 1 : 0; // auto
  db.prepare('UPDATE customers SET device_locked = ? WHERE id = ?').run(locked, customerId);
}

function customerView(c) {
  const inst = db.prepare('SELECT * FROM installments WHERE customer_id = ? ORDER BY seq').all(c.id);
  const paid = inst.filter(i => i.paid).reduce((s, i) => s + i.amount, 0);
  const total = inst.reduce((s, i) => s + i.amount, 0);
  const nextDue = inst.find(i => !i.paid) || null;
  const { pin, ...safe } = c; // never expose the hashed login PIN
  return {
    ...safe,
    selfie_url: c.selfie_path ? `/api/files/${c.selfie_path}` : null,
    cnic_url: c.cnic_path ? `/api/files/${c.cnic_path}` : null,
    joint_url: c.joint_path ? `/api/files/${c.joint_path}` : null,
    installments: inst,
    summary: {
      total_financed: Math.round(total * 100) / 100,
      paid: Math.round(paid * 100) / 100,
      remaining: Math.round((total - paid) * 100) / 100,
      overdue: overdueCount(c.id),
      next_due: nextDue ? { seq: nextDue.seq, amount: nextDue.amount, due_date: nextDue.due_date } : null,
    },
  };
}

// ---------- routes ----------
const routes = [];
function route(method, pattern, handler) {
  const keys = [];
  const rx = new RegExp('^' + pattern.replace(/:[^/]+/g, (m) => { keys.push(m.slice(1)); return '([^/]+)'; }) + '$');
  routes.push({ method, rx, keys, handler });
}

// --- Auth ---
route('POST', '/api/auth/register-agent', async (req, res) => {
  const b = await readBody(req);
  if (!b.name || !b.phone || !b.password) return send(res, 400, { error: 'name, phone, password required' });
  const exists = db.prepare('SELECT id FROM users WHERE phone = ?').get(b.phone);
  if (exists) return send(res, 409, { error: 'phone already registered' });
  const info = db.prepare(
    "INSERT INTO users (role, name, shop_name, phone, password, status) VALUES ('agent',?,?,?,?,'pending')"
  ).run(b.name, b.shop_name || null, b.phone, hashPassword(b.password));
  send(res, 201, { id: info.lastInsertRowid, status: 'pending', message: 'Account created. Waiting for admin approval.' });
});

route('POST', '/api/auth/login', async (req, res) => {
  const b = await readBody(req);
  const u = db.prepare('SELECT * FROM users WHERE phone = ?').get(b.phone || '');
  if (!u || !verifyPassword(b.password || '', u.password)) return send(res, 401, { error: 'invalid phone or password' });
  if (u.status === 'pending') return send(res, 403, { error: 'account pending admin approval' });
  if (u.status === 'suspended') return send(res, 403, { error: 'account suspended' });
  const token = signToken({ uid: u.id, role: u.role });
  send(res, 200, { token, user: { id: u.id, role: u.role, name: u.name, shop_name: u.shop_name, phone: u.phone } });
});

route('GET', '/api/me', async (req, res, _p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  send(res, 200, { user });
});

// --- Admin: agents ---
route('GET', '/api/admin/agents', async (req, res, _p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  const rows = db.prepare("SELECT id, name, shop_name, phone, status, created_at FROM users WHERE role='agent' ORDER BY created_at DESC").all();
  send(res, 200, { agents: rows });
});
route('POST', '/api/admin/agents/:id/approve', async (req, res, p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  db.prepare("UPDATE users SET status='active' WHERE id=? AND role='agent'").run(p.id);
  send(res, 200, { ok: true });
});
route('POST', '/api/admin/agents/:id/suspend', async (req, res, p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  db.prepare("UPDATE users SET status='suspended' WHERE id=? AND role='agent'").run(p.id);
  send(res, 200, { ok: true });
});

// --- Admin: enrollment approvals ---
route('GET', '/api/admin/enrollments', async (req, res, _p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  const status = new URL(req.url, 'http://x').searchParams.get('status') || 'pending';
  const rows = db.prepare(`
    SELECT c.*, u.name agent_name, u.shop_name agent_shop
    FROM customers c JOIN users u ON u.id = c.agent_id
    WHERE c.status = ? ORDER BY c.created_at DESC`).all(status);
  send(res, 200, { enrollments: rows.map(customerView) });
});
route('POST', '/api/admin/customers/:id/approve', async (req, res, p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  const c = db.prepare('SELECT * FROM customers WHERE id = ?').get(p.id);
  if (!c) return send(res, 404, { error: 'not found' });
  if (c.status !== 'pending') return send(res, 400, { error: 'already processed' });
  db.prepare("UPDATE customers SET status='active' WHERE id=?").run(c.id);
  const fresh = db.prepare('SELECT * FROM customers WHERE id = ?').get(c.id);
  generateSchedule(fresh);
  refreshLockState(c.id);
  send(res, 200, { ok: true });
});
route('POST', '/api/admin/customers/:id/reject', async (req, res, p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  const b = await readBody(req);
  db.prepare("UPDATE customers SET status='rejected', reject_reason=? WHERE id=? AND status='pending'").run(b.reason || null, p.id);
  send(res, 200, { ok: true });
});

// --- Create a customer (agent -> pending; admin -> active immediately) ---
route('POST', '/api/customers', async (req, res, _p, user) => {
  if (!user || (user.role !== 'agent' && user.role !== 'admin')) return send(res, 403, { error: 'not allowed' });
  const b = await readBody(req);
  if (!b.name || !b.phone) return send(res, 400, { error: 'name and phone required' });
  if (!b.selfie || !b.cnic_photo || !b.joint) return send(res, 400, { error: 'customer selfie, CNIC photo, and customer+shopkeeper photo are all required' });
  const selfie_path = saveImage(b.selfie, 'selfie');
  const cnic_path = saveImage(b.cnic_photo, 'cnic');
  const joint_path = saveImage(b.joint, 'joint');
  if (!selfie_path || !cnic_path || !joint_path) return send(res, 400, { error: 'images must be base64 data URLs (png/jpg/webp)' });
  // customer login PIN: use provided, else auto-generate a 4-digit PIN
  const plainPin = (b.pin && /^\d{4,6}$/.test(String(b.pin))) ? String(b.pin) : String(Math.floor(1000 + Math.random() * 9000));
  // admin-created sales are enrolled immediately (admin is the approver); agent sales wait for approval
  const status = user.role === 'admin' ? 'active' : 'pending';
  const device_id = (b.device_id && String(b.device_id).trim()) ? String(b.device_id).trim() : null;
  const info = db.prepare(`
    INSERT INTO customers (agent_id, name, phone, cnic, selfie_path, cnic_path, joint_path, product, total_price, down_payment, months, status, pin, device_id)
    VALUES (?,?,?,?,?,?,?,?,?,?,?, ?, ?, ?)`).run(
    user.id, b.name, b.phone, b.cnic || null, selfie_path, cnic_path, joint_path, b.product || null,
    Number(b.total_price) || 0, Number(b.down_payment) || 0, Number(b.months) || 0, status, hashPassword(plainPin), device_id);
  if (status === 'active') {
    const fresh = db.prepare('SELECT * FROM customers WHERE id = ?').get(info.lastInsertRowid);
    generateSchedule(fresh);
    refreshLockState(info.lastInsertRowid);
  }
  send(res, 201, { id: info.lastInsertRowid, status, pin: plainPin,
    message: status === 'active'
      ? 'Customer enrolled. Share the login PIN with the customer.'
      : 'Enrollment submitted for admin approval. Share the login PIN with the customer.' });
});
route('GET', '/api/customers', async (req, res, _p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const rows = user.role === 'admin'
    ? db.prepare('SELECT * FROM customers ORDER BY created_at DESC').all()
    : db.prepare('SELECT * FROM customers WHERE agent_id = ? ORDER BY created_at DESC').all(user.id);
  send(res, 200, { customers: rows.map(customerView) });
});
route('GET', '/api/customers/:id', async (req, res, p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const c = db.prepare('SELECT * FROM customers WHERE id = ?').get(p.id);
  if (!c) return send(res, 404, { error: 'not found' });
  if (user.role === 'agent' && c.agent_id !== user.id) return send(res, 403, { error: 'forbidden' });
  refreshLockState(c.id);
  send(res, 200, { customer: customerView(db.prepare('SELECT * FROM customers WHERE id = ?').get(c.id)) });
});

// --- Payments / installments ---
route('POST', '/api/installments/:id/pay', async (req, res, p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const b = await readBody(req);
  const inst = db.prepare('SELECT * FROM installments WHERE id = ?').get(p.id);
  if (!inst) return send(res, 404, { error: 'not found' });
  const c = db.prepare('SELECT * FROM customers WHERE id = ?').get(inst.customer_id);
  if (user.role === 'agent' && c.agent_id !== user.id) return send(res, 403, { error: 'forbidden' });
  if (inst.paid) return send(res, 400, { error: 'already paid' });
  db.prepare("UPDATE installments SET paid=1, paid_at=datetime('now'), method=?, txn_ref=? WHERE id=?")
    .run(b.method || 'cash', b.txn_ref || null, inst.id);
  // complete customer if all paid
  const remaining = db.prepare('SELECT COUNT(*) c FROM installments WHERE customer_id=? AND paid=0').get(inst.customer_id).c;
  if (remaining === 0) db.prepare("UPDATE customers SET status='completed', device_locked=0 WHERE id=?").run(inst.customer_id);
  else refreshLockState(inst.customer_id);
  send(res, 200, { ok: true, remaining });
});

// --- Reminders: installments due within 2 days, unpaid ---
route('GET', '/api/reminders', async (req, res, _p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const t = today();
  const d = new Date(t + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + 2);
  const limit = d.toISOString().slice(0, 10);
  const base = `
    SELECT i.id, i.seq, i.amount, i.due_date, c.id customer_id, c.name customer_name, c.phone customer_phone, c.agent_id
    FROM installments i JOIN customers c ON c.id = i.customer_id
    WHERE i.paid = 0 AND c.status = 'active' AND i.due_date <= ?`;
  const rows = user.role === 'admin'
    ? db.prepare(base + ' ORDER BY i.due_date').all(limit)
    : db.prepare(base + ' AND c.agent_id = ? ORDER BY i.due_date').all(limit, user.id);
  send(res, 200, { reminders: rows, as_of: t, through: limit });
});

// --- Admin: manual test lock / unlock (for testing without waiting for a due date) ---
route('POST', '/api/admin/customers/:id/locktest', async (req, res, p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  const b = await readBody(req);
  const val = b.mode === 'lock' ? 1 : b.mode === 'unlock' ? 0 : null; // lock / unlock / auto
  db.prepare('UPDATE customers SET force_lock = ? WHERE id = ?').run(val, p.id);
  refreshLockState(p.id);
  const c = db.prepare('SELECT device_locked FROM customers WHERE id = ?').get(p.id);
  send(res, 200, { ok: true, locked: !!(c && c.device_locked) });
});

// --- Device lock polling (used by the lock APK) ---
route('POST', '/api/device/register', async (req, res, _p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const b = await readBody(req);
  const c = db.prepare('SELECT * FROM customers WHERE id = ?').get(b.customer_id);
  if (!c) return send(res, 404, { error: 'customer not found' });
  if (user.role === 'agent' && c.agent_id !== user.id) return send(res, 403, { error: 'forbidden' });
  db.prepare('UPDATE customers SET device_id = ? WHERE id = ?').run(b.device_id || null, c.id);
  send(res, 200, { ok: true });
});
// Lock app polls this (device_id acts as shared identifier). Returns whether device should be locked.
route('GET', '/api/device/status', async (req, res) => {
  const device_id = new URL(req.url, 'http://x').searchParams.get('device_id');
  if (!device_id) return send(res, 400, { error: 'device_id required' });
  const c = db.prepare('SELECT * FROM customers WHERE device_id = ?').get(device_id);
  if (!c) return send(res, 404, { error: 'device not registered' });
  refreshLockState(c.id);
  const fresh = db.prepare('SELECT device_locked, status, force_lock FROM customers WHERE id = ?').get(c.id);
  // next_lock_date = the date on/after which the device must be locked if still unpaid.
  // The app stores this so it can enforce the lock OFFLINE (no internet can't dodge the lock).
  let next_lock_date = null;
  if (fresh.force_lock === 1) next_lock_date = today();                 // manual/test lock -> lock now
  else if (fresh.force_lock === 0) next_lock_date = null;               // manual unlock -> never
  else if (fresh.status === 'active') {
    const row = db.prepare('SELECT MIN(due_date) d FROM installments WHERE customer_id=? AND paid=0').get(c.id);
    next_lock_date = row && row.d ? row.d : null;                       // earliest unpaid due date
  }
  const grace_days = Number(process.env.GRACE_DAYS || 2);              // offline tolerance
  send(res, 200, {
    locked: !!fresh.device_locked,
    status: fresh.status,
    next_lock_date,            // YYYY-MM-DD or null — lock if today >= this date
    grace_days,                // if offline longer than this many days -> lock
    server_date: today(),
    message: fresh.device_locked
      ? 'Aapki installment due hai. Bara-e-karam ada karein taake phone unlock ho jaye.'
      : 'OK',
  });
});

// ========== CUSTOMER PORTAL ==========
function authCustomer(req) {
  const h = req.headers['authorization'] || '';
  const token = h.startsWith('Bearer ') ? h.slice(7) : null;
  if (!token) return null;
  const payload = verifyToken(token);
  if (!payload || payload.role !== 'customer') return null;
  const c = db.prepare('SELECT * FROM customers WHERE id = ?').get(payload.cid);
  return c || null;
}
function payConfig() {
  return {
    jazzcash: process.env.PAY_JAZZCASH || '',
    easypaisa: process.env.PAY_EASYPAISA || '',
    account_name: process.env.PAY_ACCOUNT_NAME || 'Paymint',
  };
}

route('POST', '/api/customer/login', async (req, res) => {
  const b = await readBody(req);
  const c = db.prepare('SELECT * FROM customers WHERE phone = ? ORDER BY id DESC').get(b.phone || '');
  if (!c || !c.pin || !verifyPassword(b.pin || '', c.pin)) return send(res, 401, { error: 'invalid phone or PIN' });
  if (c.status === 'pending') return send(res, 403, { error: 'your enrollment is awaiting approval' });
  if (c.status === 'rejected') return send(res, 403, { error: 'enrollment was not approved' });
  const token = signToken({ cid: c.id, role: 'customer' });
  send(res, 200, { token, name: c.name });
});

route('GET', '/api/customer/me', async (req, res) => {
  const c = authCustomer(req);
  if (!c) return send(res, 401, { error: 'unauthorized' });
  refreshLockState(c.id);
  const fresh = db.prepare('SELECT * FROM customers WHERE id = ?').get(c.id);
  const v = customerView(fresh);
  delete v.pin; delete v.selfie_path; delete v.cnic_path;
  const pending = db.prepare("SELECT id, installment_id, amount, method, txn_ref, status, created_at FROM payment_requests WHERE customer_id=? ORDER BY created_at DESC LIMIT 20").all(c.id);
  send(res, 200, { customer: v, pay: payConfig(), requests: pending });
});

// Customer submits a payment (creates a request the agent/admin confirms)
route('POST', '/api/customer/pay', async (req, res) => {
  const c = authCustomer(req);
  if (!c) return send(res, 401, { error: 'unauthorized' });
  const b = await readBody(req);
  const inst = db.prepare('SELECT * FROM installments WHERE id = ? AND customer_id = ?').get(b.installment_id, c.id);
  if (!inst) return send(res, 404, { error: 'installment not found' });
  if (inst.paid) return send(res, 400, { error: 'this installment is already paid' });
  const dup = db.prepare("SELECT id FROM payment_requests WHERE installment_id=? AND status='pending'").get(inst.id);
  if (dup) return send(res, 400, { error: 'a payment for this installment is already under review' });
  db.prepare('INSERT INTO payment_requests (customer_id, installment_id, amount, method, txn_ref) VALUES (?,?,?,?,?)')
    .run(c.id, inst.id, inst.amount, b.method || 'jazzcash', (b.txn_ref || '').slice(0, 60));
  send(res, 201, { ok: true, message: 'Payment submitted. It will be confirmed shortly.' });
});

// ========== PAYMENT REQUESTS (agent/admin) ==========
route('GET', '/api/payments', async (req, res, _p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const status = new URL(req.url, 'http://x').searchParams.get('status') || 'pending';
  const base = `
    SELECT pr.*, c.name customer_name, c.phone customer_phone, c.agent_id, i.seq
    FROM payment_requests pr
    JOIN customers c ON c.id = pr.customer_id
    LEFT JOIN installments i ON i.id = pr.installment_id
    WHERE pr.status = ?`;
  const rows = user.role === 'admin'
    ? db.prepare(base + ' ORDER BY pr.created_at DESC').all(status)
    : db.prepare(base + ' AND c.agent_id = ? ORDER BY pr.created_at DESC').all(status, user.id);
  send(res, 200, { payments: rows });
});
route('POST', '/api/payments/:id/approve', async (req, res, p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const pr = db.prepare('SELECT * FROM payment_requests WHERE id = ?').get(p.id);
  if (!pr || pr.status !== 'pending') return send(res, 404, { error: 'not found or already processed' });
  const c = db.prepare('SELECT * FROM customers WHERE id = ?').get(pr.customer_id);
  if (user.role === 'agent' && c.agent_id !== user.id) return send(res, 403, { error: 'forbidden' });
  if (pr.installment_id) {
    db.prepare("UPDATE installments SET paid=1, paid_at=datetime('now'), method=?, txn_ref=? WHERE id=? AND paid=0")
      .run(pr.method, pr.txn_ref, pr.installment_id);
  }
  db.prepare("UPDATE payment_requests SET status='approved' WHERE id=?").run(pr.id);
  const remaining = db.prepare('SELECT COUNT(*) c FROM installments WHERE customer_id=? AND paid=0').get(pr.customer_id).c;
  if (remaining === 0) db.prepare("UPDATE customers SET status='completed', device_locked=0 WHERE id=?").run(pr.customer_id);
  else refreshLockState(pr.customer_id);
  send(res, 200, { ok: true, remaining });
});
route('POST', '/api/payments/:id/reject', async (req, res, p, user) => {
  if (!user) return send(res, 401, { error: 'unauthorized' });
  const pr = db.prepare('SELECT * FROM payment_requests WHERE id = ?').get(p.id);
  if (!pr) return send(res, 404, { error: 'not found' });
  const c = db.prepare('SELECT * FROM customers WHERE id = ?').get(pr.customer_id);
  if (user.role === 'agent' && c.agent_id !== user.id) return send(res, 403, { error: 'forbidden' });
  db.prepare("UPDATE payment_requests SET status='rejected' WHERE id=?").run(pr.id);
  send(res, 200, { ok: true });
});

// --- Public: site info (contact email) for the landing page ---
route('GET', '/api/public/info', async (req, res) => {
  send(res, 200, { contact_email: process.env.CONTACT_EMAIL || 'support@paymint.pk' });
});

// --- Public: contact / partner inquiry from the landing page ---
route('POST', '/api/contact', async (req, res) => {
  const b = await readBody(req);
  if (!b.name || (!b.phone && !b.email)) return send(res, 400, { error: 'name and a phone or email are required' });
  const type = ['dealer', 'customer', 'general'].includes(b.type) ? b.type : 'general';
  db.prepare('INSERT INTO leads (type, name, phone, email, message) VALUES (?,?,?,?,?)')
    .run(type, String(b.name).slice(0, 120), (b.phone || '').slice(0, 40), (b.email || '').slice(0, 120), (b.message || '').slice(0, 2000));
  send(res, 201, { ok: true, message: 'Thanks! We will get back to you soon.' });
});

// --- Admin: inquiries from the landing page ---
route('GET', '/api/admin/inquiries', async (req, res, _p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  const rows = db.prepare('SELECT * FROM leads ORDER BY status ASC, created_at DESC').all();
  send(res, 200, { inquiries: rows });
});
route('POST', '/api/admin/inquiries/:id/resolve', async (req, res, p, user) => {
  if (!user || user.role !== 'admin') return send(res, 403, { error: 'admin only' });
  db.prepare("UPDATE leads SET status='done' WHERE id=?").run(p.id);
  send(res, 200, { ok: true });
});

// ---------- static + files ----------
const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.png': 'image/png', '.jpg': 'image/jpeg', '.webp': 'image/webp', '.svg': 'image/svg+xml' };
function serveStatic(res, filePath) {
  fs.readFile(filePath, (err, data) => {
    if (err) return send(res, 404, { error: 'not found' });
    res.writeHead(200, { 'Content-Type': MIME[path.extname(filePath)] || 'application/octet-stream' });
    res.end(data);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://x');
    const pathname = decodeURIComponent(url.pathname);

    // uploaded files (auth-gated)
    if (pathname.startsWith('/api/files/')) {
      const user = authUser(req);
      if (!user) return send(res, 401, { error: 'unauthorized' });
      const name = path.basename(pathname.slice('/api/files/'.length));
      return serveStatic(res, path.join(UPLOAD_DIR, name));
    }

    if (pathname.startsWith('/api/')) {
      const match = routes.find(r => r.method === req.method && r.rx.test(pathname));
      if (!match) return send(res, 404, { error: 'route not found' });
      const m = pathname.match(match.rx);
      const params = {};
      match.keys.forEach((k, i) => { params[k] = m[i + 1]; });
      const needsAuth = !['/api/auth/login', '/api/auth/register-agent', '/api/device/status', '/api/contact', '/api/public/info',
        '/api/customer/login', '/api/customer/me', '/api/customer/pay'].includes(pathname);
      const user = authUser(req);
      if (needsAuth && !user) return send(res, 401, { error: 'unauthorized' });
      return match.handler(req, res, params, user);
    }

          if (pathname === '/app' || pathname.startsWith('/app/')) {
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        return res.end(EMBEDDED_HTML);
      }
      if (pathname === '/me' || pathname.startsWith('/me/')) {
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        return res.end(EMBEDDED_CUSTOMER);
      }
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return res.end(EMBEDDED_LANDING);
  } catch (e) {
    send(res, e.message === 'invalid JSON' || e.message === 'payload too large' ? 400 : 500, { error: e.message });
  }
});

server.listen(PORT, () => console.log(`Paymint backend running on http://localhost:${PORT}`));

